pqc_sizes = {
    'RSA‑2048': {'type': 'KEM', 'pub': 256, 'ct/sig': 256},
    'Kyber‑768': {'type': 'KEM', 'pub': 1184, 'ct': 1088},
    'ECDSA P‑256': {'type': 'Sig', 'pub': 64, 'sig': 64},
    'Dilithium‑3': {'type': 'Sig', 'pub': 1952, 'sig': 3293},
    'Falcon‑512': {'type': 'Sig', 'pub': 897, 'sig': 666},
    'SPHINCS+‑128s': {'type': 'Sig', 'pub': 32, 'sig': 7856}
}
for alg, info in pqc_sizes.items():
    print(f"{alg}: pub={info['pub']}B, {'ct' if info['type']=='KEM' else 'sig'}={info.get('ct',info['sig'])}B")
